1	//! AgentX subagent for app_moxa_framework (Plan D B).
2	//!
3	//! B1 (Design C): the framework, as an AgentX subagent, FULLY owns the config
4	//! OIDs listed in `lib_moxa_ies_auto_mibs` (the dlmod is removed).
5	//! - GET maps OID -> config-layer URI and reads the value in-process via
6	//!   `config_operation::get_config_from_path` + `remove_password_from_config` —
7	//!   the exact pair the REST `_setting_get` uses (byte-identical, fast).
8	//! - SET reuses the framework's own REST PATCH via `ies_config_set` — the exact
9	//!   loopback path the dlmod used (byte-identical; SET is rare, latency moot).
10	
11	use std::collections::HashMap;
12	use std::os::raw::{c_int, c_uint, c_void};
13	use std::sync::{Arc, Mutex, OnceLock};
14	use std::time::{Duration, Instant};
15	
16	use lib_moxa_rust_ies_auto_mibs::col;
17	use lib_moxa_rust_snmp_agentx as agentx;
18	use plugins_moxa_framework::config::Plugins;
19	use qstring::QString;
20	use rust_moxa_common::config_configs::Configs;
21	use rust_moxa_common::user_info::{UserInfo, UserInfoRole};
22	use rust_moxa_config_layer::config_operation;
23	use rust_moxa_status_operation::StatusOperation;
24	
25	/// How long a per-plugin status snapshot stays valid (mirrors in-master table
26	/// snapshot reuse across a walk). plugin_moxa_io has cache_timeout=0, so without
27	/// this every OID would re-scan hardware.
28	const STATUS_SNAP_TTL: Duration = Duration::from_secs(2);
29	
30	/// Per-plugin status root, refreshed at most once per TTL on the AgentX thread.
31	struct StatusSnap {
32	    /// plugin name -> (fetched_at, plugin status object)
33	    by_plugin: HashMap<String, (Instant, serde_json::Value)>,
34	}
35	
36	/// Live handles into the running framework state, shared with the subagent
37	/// thread (same `Arc<Mutex<…>>` the actix workers use).
38	struct SubagentState {
39	    plugins: Arc<Mutex<Plugins>>,
40	    configs: Arc<Mutex<Configs>>,
41	    status_operation: Arc<Mutex<StatusOperation>>,
42	    plugins_status: Arc<Mutex<plugins_moxa_framework::status::Plugins>>,
43	    status_snap: Mutex<StatusSnap>,
44	}
45	
46	static STATE: OnceLock<SubagentState> = OnceLock::new();
47	
48	/// Fixed read identity for SNMP GETs (Task 5): reads are identity-less — VACM
49	/// authorizes at the master and per-OID config values are uniform. Matches the
50	/// admin identity `LibUtil_CreateToken` bakes for today's SNMP reads.
51	fn sys_read_userinfo() -> UserInfo {
52	    UserInfo {
53	        username: "snmp@moxa^service".to_string(),
54	        role: UserInfoRole::admin,
55	        nonce: String::new(),
56	        from_ip: "127.0.0.1".to_string(),
57	    }
58	}
59	
60	/// First path segment = status plugin name (e.g. "io" from "io/power/system/0").
61	fn status_plugin_name(path: &str) -> Option<&str> {
62	    path.split('/').find(|s| !s.is_empty())
63	}
64	
65	/// Walk `path` under a plugin status root. The first segment is the plugin name
66	/// (already selected); remaining segments index into `root`.
67	fn navigate_plugin_status(root: &serde_json::Value, path: &str) -> serde_json::Value {
68	    let mut cur = root;
69	    let mut skip_plugin = true;
70	    for attr in path.split('/').filter(|s| !s.is_empty()) {
71	        if skip_plugin {
72	            skip_plugin = false;
73	            continue;
74	        }
75	        cur = match attr.parse::<usize>() {
76	            Ok(i) => &cur[i],
77	            Err(_) => &cur[attr],
78	        };
79	        if cur.is_null() {
80	            return serde_json::Value::Null;
81	        }
82	    }
83	    cur.clone()
84	}
85	
86	/// Status GET with a short per-plugin snapshot (fix 2): one `get_status` per
87	/// plugin per TTL, then path navigation in-process — same idea as in-master's
88	/// table snapshot, so a walk does not re-hit hardware for every OID.
89	fn get_status_with_snap(
90	    state: &SubagentState,
91	    path: &str,
92	) -> Result<serde_json::Value, ()> {
93	    let plugin = status_plugin_name(path).ok_or(())?;
94	    {
95	        let snap = state.status_snap.lock().unwrap();
96	        if let Some((at, root)) = snap.by_plugin.get(plugin) {
97	            if at.elapsed() < STATUS_SNAP_TTL {
98	                return Ok(navigate_plugin_status(root, path));
99	            }
100	        }
101	    }
102	
103	    let ui = sys_read_userinfo();
104	    let query = QString::from("");
105	    let root = {
106	        let mut status_op = state.status_operation.lock().unwrap();
107	        let mut plugins_status = state.plugins_status.lock().unwrap();
108	        status_op
109	            .get_status_from_path(&mut plugins_status, plugin, &ui, &query)
110	            .map_err(|_| ())?
111	    };
112	    let value = navigate_plugin_status(&root, path);
113	    state
114	        .status_snap
115	        .lock()
116	        .unwrap()
117	        .by_plugin
118	        .insert(plugin.to_string(), (Instant::now(), root));
119	    Ok(value)
120	}
121	
122	/// Read-only GET handler shared by every registered config OID.
123	fn handle_get(requests: *mut c_void) -> c_int {
124	    let state = match STATE.get() {
125	        Some(s) => s,
126	        None => {
127	            agentx::set_error(requests, agentx::SNMP_ERR_GENERR);
128	            return agentx::SNMP_ERR_NOERROR;
129	        }
130	    };
131	
132	    // 1. the requested OID
133	    let oid = match agentx::get_request_oid(requests) {
134	        Some(o) => o,
135	        None => {
136	            agentx::set_error(requests, agentx::SNMP_ERR_GENERR);
137	            return agentx::SNMP_ERR_NOERROR;
138	        }
139	    };
140	
141	    // 2. OID -> config-layer URI
142	    let entry = match lib_moxa_rust_ies_auto_mibs::lookup_by_oid(&oid) {
143	        Some(e) => e,
144	        None => {
145	            agentx::set_no_such_instance(requests);
146	            return agentx::SNMP_ERR_NOERROR;
147	        }
148	    };
149	
150	    // 2b. table columns:
151	    //   1 = portsPbmp index, 2 = portsPbmp value, 4 = index-table index,
152	    //   6 = RowStatus (ADR-0001).
153	    match entry.table_col {
154	        col::ROW_INDEX => {
155	            let port = *oid.last().unwrap_or(&0) as i64;
156	            agentx::set_int(requests, port);
157	            return agentx::SNMP_ERR_NOERROR;
158	        }
159	        col::PBMP_VALUE => return handle_pbmp_value_get(state, requests, &entry.uri, &oid),
160	        col::IDXTBL_INDEX => {
161	            return handle_idx_table_index_get(
162	                state,
163	                requests,
164	                &entry.uri,
165	                &oid,
166	                entry.is_status,
167	            )
168	        }
169	        col::ROWSTATUS => return handle_rowstatus_get(state, requests, &entry.uri, &oid),
170	        _ => {}
171	    }
172	
173	    // config path: index-table value col (3) -> "<uri><row-1>/<column>";
174	    // turboring ring col (5) -> "<uri>/ring<row>/<column>" (row 1-based);
175	    // a scalar (0) uses the URI as-is.
176	    let idx_path;
177	    let path: &str = if entry.table_col == col::IDXTBL_VALUE {
178	        let row = *oid.last().unwrap_or(&0);
179	        if row < 1 {
180	            agentx::set_no_such_instance(requests);
181	            return agentx::SNMP_ERR_NOERROR;
182	        }
183	        idx_path = format!("{}{}/{}", entry.uri, row - 1, entry.uri_index);
184	        &idx_path
185	    } else if entry.table_col == col::TR2RING_VALUE {
186	        let row = *oid.last().unwrap_or(&0);
187	        if row < 1 {
188	            agentx::set_no_such_instance(requests);
189	            return agentx::SNMP_ERR_NOERROR;
190	        }
191	        idx_path = format!("{}/ring{}/{}", entry.uri, row, entry.uri_index);
192	        &idx_path
193	    } else {
194	        &entry.uri
195	    };
196	
197	    // Status-layer entry (stat/ prefix or URI_STATUS flag): read from the status
198	    // layer at `path` (a scalar's path is the URI; a table's is the row path).
199	    if entry.is_status {
200	        return handle_status_get(state, requests, path, entry.val_type);
201	    }
202	
203	    // 3. read the value in-process — byte-identical to REST `_setting_get`.
204	    //    Lock order (configs then plugins) matches config_layer::setting_read.
205	    let ui = sys_read_userinfo();
206	    let configs = state.configs.lock().unwrap();
207	    let mut plugins = state.plugins.lock().unwrap();
208	
209	    let value = match config_operation::get_config_from_path(
210	        &mut plugins,
211	        &ui,
212	        path,
213	        &configs.running_config,
214	        None,
215	        false,
216	    ) {
217	        Ok(v) => v,
218	        Err(_) => {
219	            // Config path not present (missing row / a URI needing a remap we
220	            // don't apply) -> noSuchInstance so a walk continues.
221	            agentx::set_no_such_instance(requests);
222	            return agentx::SNMP_ERR_NOERROR;
223	        }
224	    };
225	    let value = if value.is_null() {
226	        value
227	    } else {
228	        match config_operation::remove_password_from_config(&mut plugins, path, value) {
229	            Ok(v) => v,
230	            Err(_) => {
231	                agentx::set_no_such_instance(requests);
232	                return agentx::SNMP_ERR_NOERROR;
233	            }
234	        }
235	    };
236	
237	    // 4. set the value per the mapped type (byte-identical to the old handler).
238	    match entry.val_type {
239	        agentx::ASN_INTEGER => {
240	            // Config leaf may be a JSON bool (true->1, false->2, per SNMPv2
241	            // TruthValue == ies-auto-mibs get_value.c:95), a number, or a
242	            // numeric string; accept all three.
243	            let n = value
244	                .as_i64()
245	                .or_else(|| value.as_bool().map(|b| if b { 1 } else { 2 }))
246	                .or_else(|| value.as_str().and_then(|s| s.parse().ok()));
247	            match n {
248	                Some(n) => {
249	                    agentx::set_int(requests, n);
250	                }
251	                None => {
252	                    agentx::set_no_such_instance(requests);
253	                }
254	            }
255	        }
256	        _ => match value.as_str() {
257	            Some(s) => {
258	                agentx::set_octet_string(requests, s);
259	            }
260	            None => {
261	                agentx::set_no_such_instance(requests);
262	            }
263	        },
264	    }
265	    agentx::SNMP_ERR_NOERROR
266	}
267	
268	/// GET for a portsPbmp value column: read the per-port boolean array at `uri`
269	/// and return `array[port-1]` as a TruthValue (true->1, false->2).
270	fn handle_pbmp_value_get(
271	    state: &SubagentState,
272	    requests: *mut c_void,
273	    uri: &str,
274	    oid: &[agentx::Oid],
275	) -> c_int {
276	    let port = match oid.last() {
277	        Some(&p) if p >= 1 => p as usize,
278	        _ => {
279	            agentx::set_no_such_instance(requests);
280	            return agentx::SNMP_ERR_NOERROR;
281	        }
282	    };
283	    let ui = sys_read_userinfo();
284	    let configs = state.configs.lock().unwrap();
285	    let mut plugins = state.plugins.lock().unwrap();
286	    let arr = match config_operation::get_config_from_path(
287	        &mut plugins,
288	        &ui,
289	        uri,
290	        &configs.running_config,
291	        None,
292	        false,
293	    ) {
294	        Ok(v) => v,
295	        Err(_) => {
296	            agentx::set_no_such_instance(requests);
297	            return agentx::SNMP_ERR_NOERROR;
298	        }
299	    };
300	    // `arr` is the JSON boolean array; the SNMP value is array[port-1].
301	    match arr.get(port - 1) {
302	        Some(v) => {
303	            let n = v
304	                .as_bool()
305	                .map(|b| if b { 1 } else { 2 })
306	                .or_else(|| v.as_i64());
307	            match n {
308	                Some(n) => {
309	                    agentx::set_int(requests, n);
310	                }
311	                None => {
312	                    agentx::set_no_such_instance(requests);
313	                }
314	            }
315	        }
316	        None => {
317	            agentx::set_no_such_instance(requests);
318	        }
319	    }
320	    agentx::SNMP_ERR_NOERROR
321	}
322	
323	/// SET for a portsPbmp value column: read the per-port boolean array, flip
324	/// `array[port-1]` to the incoming TruthValue (1 -> true, else -> false), and
325	/// PATCH the whole array back. Returns 0 on success, non-zero on failure.
326	fn handle_pbmp_value_set(uri: &str, requests: *mut c_void) -> i32 {
327	    let state = match STATE.get() {
328	        Some(s) => s,
329	        None => return -1,
330	    };
331	    let oid = match agentx::get_request_oid(requests) {
332	        Some(o) => o,
333	        None => return -1,
334	    };
335	    let port = match oid.last() {
336	        Some(&p) if p >= 1 => p as usize,
337	        _ => return -1,
338	    };
339	    let sv = match agentx::get_set_int(requests) {
340	        Some(v) => v,
341	        None => return -1,
342	    };
343	
344	    // Read the current array (lock order: configs then plugins).
345	    let mut bools: Vec<bool> = {
346	        let ui = sys_read_userinfo();
347	        let configs = state.configs.lock().unwrap();
348	        let mut plugins = state.plugins.lock().unwrap();
349	        let arr = match config_operation::get_config_from_path(
350	            &mut plugins,
351	            &ui,
352	            uri,
353	            &configs.running_config,
354	            None,
355	            false,
356	        ) {
357	            Ok(v) => v,
358	            Err(_) => return -1,
359	        };
360	        match arr.as_array() {
361	            Some(a) => a.iter().map(|v| v.as_bool().unwrap_or(false)).collect(),
362	            None => return -1,
363	        }
364	    };
365	    if port - 1 >= bools.len() {
366	        return -1;
367	    }
368	    bools[port - 1] = sv == 1;
369	
370	    // Serialize "[true,false,…]" by hand (no serde_json dep) and PATCH it whole.
371	    let json = format!(
372	        "[{}]",
373	        bools
374	            .iter()
375	            .map(|b| if *b { "true" } else { "false" })
376	            .collect::<Vec<_>>()
377	            .join(",")
378	    );
379	    lib_moxa_rust_ies_auto_mibs::config_set_json(uri, &json)
380	}
381	
382	/* SNMP RowStatus (RFC 2579) — same integers as MOXA_SNMP_READ_CREATE_*. */
383	const RS_ACTIVE: i64 = 1;
384	const RS_NOT_IN_SERVICE: i64 = 2;
385	const RS_CREATE_AND_GO: i64 = 4;
386	const RS_CREATE_AND_WAIT: i64 = 5;
387	const RS_DESTROY: i64 = 6;
388	
389	/// Config array path for an index-table URI base (`"snmpTrap/host/"` -> `"snmpTrap/host"`).
390	fn index_table_array_uri(uri: &str) -> &str {
391	    uri.strip_suffix('/').unwrap_or(uri)
392	}
393	
394	fn read_config_value(state: &SubagentState, path: &str) -> Result<serde_json::Value, ()> {
395	    let ui = sys_read_userinfo();
396	    let configs = state.configs.lock().unwrap();
397	    let mut plugins = state.plugins.lock().unwrap();
398	    config_operation::get_config_from_path(
399	        &mut plugins,
400	        &ui,
401	        path,
402	        &configs.running_config,
403	        None,
404	        false,
405	    )
406	    .map_err(|_| ())
407	}
408	
409	/// GET RowStatus: missing row -> noSuchInstance; `valid` true/absent -> active(1);
410	/// `valid` false -> notInService(2). Mirrors in-master mapping onto config `valid`.

