630	/// Moxa data-type tag for a MacAddress column (ies_auto_mibs.h SNMP_DATA_TYPE_MAC_ADDRESS
631	/// = 0xf4). Carried through unchanged in `MapEntry.val_type`, so it is distinguishable
632	/// from a plain OCTET string (0x04) here.
633	const SNMP_DATA_TYPE_MAC: c_int = 0xf4;
634	
635	/// Parse the first 6 colon-separated hex octets of a MAC string to 6 raw bytes —
636	/// byte-identical to the in-master C engine (moxa_snmp_handle_util.c: reads exactly
637	/// 6 groups, ignoring any extra, e.g. turboRing's 7-group status form
638	/// "00:00:00:00:00:00:00"). `None` if fewer than 6 groups or a group is not hex.
639	fn mac_to_bytes(s: &str) -> Option<[u8; 6]> {
640	    let mut out = [0u8; 6];
641	    let mut it = s.split(':');
642	    for slot in out.iter_mut() {
643	        *slot = u8::from_str_radix(it.next()?, 16).ok()?;
644	    }
645	    Some(out)
646	}
