/* turboring config ring table: named-key config ({ring1,ring2}), path
 * "<mod_uri>/ring<N>/<column>" (N = ring number, 1-based). 2 rings, fixed.
 * index column -> row number; enable/master -> config value (table_col 5);
 * "interface" (REDUNDANT_PORT) is deferred (skipped). */
#define TR2_RING_NUM 2

static int
is_turboring_ring(const struct ies_auto_mibs_entry *e)
{
    return strcmp(e->uri, "config/turboringv2/ring/") == 0 &&
           (strcmp(e->uri_index, "index") == 0 ||
            strcmp(e->uri_index, "enable") == 0 ||
            strcmp(e->uri_index, "master") == 0);
}

/* Physical port count = length of the portsPbmp config array. 0 disables table
 * expansion (falls back to skipping, as before). */
static uint32_t
system_port_num(void)
{
    uint32_t n = 0;
    if (LibSystem_GetMaxPortNumInSystem(&n) != 0 || n == 0 || n > 256)
    {
        return 0;
    }
    return n;
}

/* Fill one row: instance OID = e->oid_list + `suffix` (.0 for a scalar, or the
 * port number for a table column). Returns 0 on success. */
static int
emit_row(struct ies_map_entry *row, const struct ies_auto_mibs_entry *e,
         moxa_oid suffix, const char *uri, const char *uri_index, int table_col)
{
    moxa_oid *o;
    int j;

    o = (moxa_oid *) malloc((e->oid_len + 1) * sizeof(moxa_oid));
    if (o == NULL)
    {
        return -1;
