                int      col;
                uint32_t rows = index_table_rows(e->uri);
                uint32_t r;

                if (strcmp(e->uri_index, "index") == 0)
                {
                    col = IES_COL_IDXTBL_INDEX;
                }
                else if (strcmp(e->uri_index, "rowStatus") == 0)
                {
                    col = IES_COL_ROWSTATUS;
                }
                else
                {
                    col = IES_COL_IDXTBL_VALUE;
                }
