                    }
                }
            }
            else /* is_tr2_ring */
            {
                /* index column -> ring number; enable/master -> config value
                 * at "<uri>/ring<row>/<column>". */
                int      col = (strcmp(e->uri_index, "index") == 0)
                                   ? IES_COL_ROW_INDEX
                                   : IES_COL_TR2RING_VALUE;
