fn setting_read(
    path: String,
    req: HttpRequest,
    data: web::Data<app_state::AppState>,
) -> impl Responder {
    #[cfg(feature = "MOXA_PROFILING")]
    let _span = profile_span!("config_layer", operation = "read", path = %req.uri().path());

    // Rust: because too many "loginPolicy"
    if path == "loginPolicy" {
        mx_debug!(MODULE_LIST_ID, &format!("setting_read: {:?}", path));
    } else {
        mx_notice!(MODULE_LIST_ID, &format!("setting_read: {:?}", path));
    }

    let mut configs = data.configs.lock().unwrap();
    let mut plugins = data.plugins_config.lock().unwrap();

    // @authenticate
    let userinfo = match authenticate(
        &data,
        &path,
        //------------------------------
        utils::get_header_by_key(req.headers(), consts::AUTHORIZATION),
        req.connection_info().realip_remote_addr(),
        &mut configs,
        &req,
    ) {
        Err(e) => return common_error::__error_to_response(e),
        Ok(t) => t,
    };

    let user_mutex = data.user_mutex.lock().unwrap();
    let request_args = QString::from(req.query_string());
    // if path == "loginPolicy" {
    //     mx_debug!(
    //         MODULE_LIST_ID,
    //         &format!("request_args: {:?}", &request_args)
    //     );
    // } else {
    //     mx_notice!(
    //         MODULE_LIST_ID,
    //         &format!("request_args: {:?}", &request_args)
    //     );
    // }

    // }
    let ret_config = if user_mutex.get_opmode() != OpMode::OpModeNormal
        && user_mutex.is_acquirable(&Some(userinfo.clone()), &None)
    {
        _setting_get(
            &mut plugins,
            &userinfo,
            &path,
            &configs.pre_running_config,
            Some(&request_args),
        )
    } else {
        _setting_get(
            &mut plugins,
            &userinfo,
            &path,
            &configs.running_config,
            Some(&request_args),
        )
    };

    match ret_config {
        Ok(t) => common_error::__value_to_response(t),
        Err(e) => common_error::__error_to_response(e),
    }
}

