#ifndef _IES_AUTO_MIBS_FLAGS_mx_turboring_v2_c_
#define _IES_AUTO_MIBS_FLAGS_mx_turboring_v2_c_



ies_handle_t 
ies_auto_mibs_setup_entry_flags_mx_turboring_v2
(
    struct ies_auto_mibs_entry *entry
)
{

    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "mxL2Redundancy/turboringv2") ) 
    {
        IES_FLAG_BITS_SET(IES_FLAG_SNMP_REPLACE_TRUTH_VALUE, entry->flags);
    }
    else
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "config/turboringv2/ring/") ) 
    {
        IES_FLAG_BITS_SET(IES_FLAG_SNMP_TR2_REPLACE_URI, entry->flags);
        snprintf(entry->mod_uri, IES_MAX_URI, "turboringv2");
        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "enable") ) 
        {
            IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_MOD_BY_IDX,  entry->flags);
            IES_FLAG_BITS_SET(IES_FLAG_SNMP_REPLACE_TRUTH_VALUE, entry->flags);
        } 
        else
        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "master") ) 
        {
            IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_MOD_BY_IDX,  entry->flags);
            IES_FLAG_BITS_SET(IES_FLAG_SNMP_REPLACE_TRUTH_VALUE, entry->flags);
        } 
        else
        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "interface") ) 
        {
            IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_REDUNDANT_PORT, entry->flags);
        } 
    }
    else
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "turboringv2/coupling/enable") ) 
    {
        IES_FLAG_BITS_SET(IES_FLAG_SNMP_REPLACE_TRUTH_VALUE, entry->flags);
    }
    else
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "turboringv2/coupling/port") ) 
    {
        IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_INTERFACE, entry->flags);
    }
    else
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "turboringv2/protectoin/action") ) 
    {

        IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_MOD_ON_SET, entry->flags);
    }
    else
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "turboringv2/protectoin/releaseInterval") ) 
    {

        IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_MOD_ON_SET, entry->flags);
    }
    else
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "stat/turboringv2/ring/") ) 
    {
        IES_FLAG_BITS_SET(IES_FLAG_SNMP_TR2_REPLACE_URI, entry->flags);
        IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_STATUS,      entry->flags);
        snprintf(entry->mod_uri, IES_MAX_URI, "turboringv2");
        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "masterStatus") ) 
        {
            IES_FLAG_BITS_SET(IES_FLAG_SNMP_REPLACE_TRUTH_VALUE, entry->flags);
        }
    }
    else
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "stat/turboringv2/coupling/portStatus") )
    {
        IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_STATUS, entry->flags);
        IES_FLAG_BITS_SET(IES_FLAG_SNMP_TR2_REPLACE_URI, entry->flags);
        snprintf(entry->mod_uri, IES_MAX_URI, "turboringv2/coupling/portStatus");
    }
#if defined(MOXA_DRC)
    else
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "stat/turboringv2/ringIndex") ) 
    {
        IES_FLAG_BITS_SET(IES_FLAG_SNMP_TR2_REPLACE_URI, entry->flags);
        IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_STATUS,      entry->flags);
        snprintf(entry->mod_uri, IES_MAX_URI, "turboringv2/ringIndex");
    }
    else
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "stat/turboringv2/totalRingNumber") ) 
    {
        IES_FLAG_BITS_SET(IES_FLAG_SNMP_TR2_REPLACE_URI, entry->flags);
        IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_STATUS,      entry->flags);
        snprintf(entry->mod_uri, IES_MAX_URI, "turboringv2/totalRingNumber");
    }
    else
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "stat/turboringv2/dynRingCoupTable/") ) 
    {
        IES_FLAG_BITS_SET(IES_FLAG_SNMP_TR2_REPLACE_URI, entry->flags);
        IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_STATUS,      entry->flags);
        snprintf(entry->mod_uri, IES_MAX_URI, "turboringv2/dynRingCoupTable");
        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "couplingGroupStatus") ) 
        {
            IES_FLAG_BITS_SET(IES_FLAG_SNMP_REPLACE_TRUTH_VALUE, entry->flags);
        }
    }
#endif // MOXA_DRC

    return IES_NOERR;
}



#endif //_IES_AUTO_MIBS_FLAGS_mx_turboring_v2_c_

