/* turboring config ring table: named-key config ({ring1,ring2}), path
 * "<mod_uri>/ring<N>/<column>" (N = ring number, 1-based). 2 rings, fixed.
 * index column -> row number; enable/master -> config value (table_col 5);
 * "interface" (REDUNDANT_PORT) is deferred (skipped). */
#define TR2_RING_NUM 2

static int
is_turboring_ring(const struct ies_auto_mibs_entry *e)
{
    return strcmp(e->uri, "config/turboringv2/ring/") == 0 &&
           (strcmp(e->uri_index, "index") == 0 ||
            strcmp(e->uri_index, "enable") == 0 ||
            strcmp(e->uri_index, "master") == 0);
}

input.new_string:
/* turboring ring table (config AND status): named-key data ({ring1,ring2}), path
 * "<mod_uri>/ring<N>/<column>" (N = ring number, 1-based). 2 rings, fixed. The
 * setup fn sets mod_uri="turboringv2" for both, so the stored uri drops the
 * "config/"/"stat/" prefix; is_status (from the "stat/" prefix, mapping below)
 * then routes the status columns to the status layer. index column -> row number;
 * value columns -> IES_COL_TR2RING_VALUE. config "interface" (REDUNDANT_PORT) is
 * deferred (skipped). */
#define TR2_RING_NUM 2

static int
is_turboring_ring(const struct ies_auto_mibs_entry *e)
{
    if (strcmp(e->uri, "config/turboringv2/ring/") == 0)
    {
        return strcmp(e->uri_index, "index") == 0 ||
               strcmp(e->uri_index, "enable") == 0 ||
               strcmp(e->uri_index, "master") == 0;
    }
    /* status ring columns: {ring1,ring2} named-key, DUT-verified addressable as
     * /api/v1/status/turboringv2/ring<N>. designatedMaster is a MacAddress. */
    if (strcmp(e->uri, "stat/turboringv2/ring/") == 0)
    {
        return strcmp(e->uri_index, "index") == 0 ||
               strcmp(e->uri_index, "masterStatus") == 0 ||
               strcmp(e->uri_index, "designatedMaster") == 0 ||
               strcmp(e->uri_index, "firstPortStatus") == 0 ||
               strcmp(e->uri_index, "secondPortStatus") == 0 ||
               strcmp(e->uri_index, "brokenStatus") == 0;
    }
    return 0;
}

