fn hybrid_config_get(path: &str) -> Result<serde_json::Value, ()> {
    let state = STATE.get().ok_or(())?;
    // Fast path: read from the in-process running_config (byte-identical to REST
    // _setting_get for complete groups, ~ms). Fall back to REST only when that
    // view lacks the data (narrower running_config, e.g. mxIpIf) — this avoids
    // the ~0.8s loopback self-loop cost (subagent -> nginx -> own actix) on the
    // common path, which a walk would otherwise pay per OID.
    // Lock order (configs then plugins) matches config_layer::setting_read.
    let inproc = {
        let ui = sys_read_userinfo();
        let configs = state.configs.lock().unwrap();
        let mut plugins = state.plugins.lock().unwrap();
        match config_operation::get_config_from_path(
            &mut plugins,
            &ui,
            path,
            &configs.running_config,
            None,
            false,
        ) {
            // "present" = has data; null / empty array -> treat as missing and
            // fall back to REST (the complete, file-backed view).
            Ok(v) => {
                let present = match &v {
                    serde_json::Value::Null => false,
                    serde_json::Value::Array(a) => !a.is_empty(),
                    _ => true,
                };
                if present {
                    // Strip passwords exactly like REST _setting_get.
                    config_operation::remove_password_from_config(&mut plugins, path, v).ok()
                } else {
                    None
                }
            }
            Err(_) => None,
        }
    };
    if let Some(v) = inproc {
        return Ok(v);
    }

    // Fallback: complete, file-backed REST read (passwords stripped server-side).
    let text = lib_moxa_rust_ies_auto_mibs::config_get(path).ok_or(())?;
    serde_json::from_str(&text).map_err(|_| ())
}

