def check_dip_tr2_lock_status():
    # Check if device support DIP switch
    if libmoxa_system.is_DIP_switch_support() == False:
        return

    # Check if dipTr2LockStatus file exitsted 
    if not os.path.isfile(PATH_TO_DIP_TR2_LOCK_FILE):
        print("[ERROR] : " + PATH_TO_DIP_TR2_LOCK_FILE + " file not find")
        return

    with open(PATH_TO_DIP_TR2_LOCK_FILE, 'r') as file:
        dipTr2LockStatus = file.read(1)
        file.close()

        # dipTr2LockStatus 1 means locked, 0 means unlocked
        if dipTr2LockStatus == "1":
            raise ErrorIncorrectValue(
                "dipTr2LockStatus",
                dipTr2LockStatus,
                "Invalid: Turbo Ring V2 is locked due to DIP configuration."
            )

