23	#define IES_TOKEN_FILE "/moxa/run/auto_mibs/s_token"
24	#define IES_TOKEN_SIZE 1024
25	
26	static struct LibFrameworkUri_Handle *s_handle = NULL;
27	static char s_token[IES_TOKEN_SIZE] = {0};
28	
29	/* Lazily create the URI handle + read the admin token (once). Returns 0 on ok. */
30	static int
31	ies_set_init(void)
32	{
33	    FILE *fp;
34	    char *r;
35	
36	    if (s_handle != NULL)
37	    {
38	        return 0;
39	    }
40	
41	    fp = fopen(IES_TOKEN_FILE, "r");
42	    if (fp == NULL)
43	    {
44	        return -1;
45	    }
46	    r = fgets(s_token, sizeof(s_token), fp);
47	    fclose(fp);
48	    if (r == NULL)
49	    {
50	        return -1;
51	    }
52	
53	    s_handle = LibFrameworkUri_CreateHandle("127.0.0.1", 80);
54	    return (s_handle != NULL) ? 0 : -1;
55	}
