57	int
58	ies_config_set(const char *config_uri, const char *value)
59	{
60	    JSON_Value *set_value;
61	    JSON_Value *resp = NULL;
62	    char uri[256] = {0};
63	    int32_t result;
64	
65	    if (config_uri == NULL || value == NULL)
66	    {
67	        return -1;
68	    }
69	    if (ies_set_init() != 0)
70	    {
71	        return -1;
72	    }
73	
74	    set_value = json_value_init_string(value);
75	    if (set_value == NULL)
76	    {
77	        return -1;
78	    }
79	
80	    /* deviceName is applied through the "agent" POST endpoint (dlmod parity). */
81	    if (strcmp(config_uri, "systemInformation/deviceName") == 0)
82	    {
83	        snprintf(uri, sizeof(uri),
84	                 "/api/v1/setting/agent/systemInformation/deviceName?save");
85	        result = LibFrameworkUri_PostUri(s_handle, uri, s_token, set_value, &resp);
86	    }
87	    else
88	    {
89	        snprintf(uri, sizeof(uri), "/api/v1/setting/data/%s?save", config_uri);
90	        result = LibFrameworkUri_PatchUri(s_handle, uri, s_token, set_value, &resp);
91	    }
92	
93	    json_value_free(set_value);
94	    json_value_free(resp);
95	    return (int) result;
96	}
