1	//! lib_moxa_rust_ies_auto_mibs — Rust FFI over the C `lib_moxa_ies_auto_mibs`.
2	//!
3	//! Looks up an OID and returns its config-layer URI mapping. Links
4	//! `libmoxaiesautomibs.so` (resolved when the final binary links).
5	
6	use std::ffi::{CStr, CString};
7	use std::os::raw::{c_char, c_int, c_ulong};
8	
9	/// Same width as net-snmp `oid` / C `moxa_oid` (unsigned long).
10	pub type Oid = c_ulong;
11	
12	/// Mirrors C `struct ies_map_entry` (see lib_moxa_ies_auto_mibs.h).
13	#[repr(C)]
14	struct CIesMapEntry {
15	    oid: *const c_ulong,
16	    oid_len: usize,
17	    uri: *const c_char,
18	    uri_index: *const c_char,
19	    val_type: c_int,
20	    mode: c_int,
21	    table_col: c_int,
22	    is_status: c_int,
23	}
24	
25	#[link(name = "moxaiesautomibs")]
26	extern "C" {
27	    fn ies_map_lookup_by_oid(o: *const c_ulong, olen: usize) -> *const CIesMapEntry;
28	    fn ies_map_count() -> usize;
29	    fn ies_map_entry_at(i: usize) -> *const CIesMapEntry;
30	    fn ies_config_set(config_uri: *const c_char, value: *const c_char) -> c_int;
31	    fn ies_config_set_int(config_uri: *const c_char, value: std::os::raw::c_long) -> c_int;
32	    fn ies_config_set_bool(config_uri: *const c_char, value: c_int) -> c_int;
33	    fn ies_config_set_json(config_uri: *const c_char, json_text: *const c_char) -> c_int;
34	}
35	
36	/// `table_col` values — mirror of the C `IES_COL_*` in lib_moxa_ies_auto_mibs.h.
37	/// How the handler resolves an OID's value. Keep in sync with the C header.
38	pub mod col {
39	    pub const SCALAR: i32 = 0; // plain config leaf: get_config_from_path(uri)
40	    pub const ROW_INDEX: i32 = 1; // index column, value = trailing OID sub-id (portsPbmp / ring index)
41	    pub const PBMP_VALUE: i32 = 2; // portsPbmp value: config bool array[port-1] as TruthValue
42	    pub const IDXTBL_VALUE: i32 = 3; // index-table value: "<uri><row-1>/<column>" (0-based)
43	    pub const IDXTBL_INDEX: i32 = 4; // index-table index: trailing OID sub-id, if the row exists
44	    pub const TR2RING_VALUE: i32 = 5; // turboring ring value: "<uri>/ring<row>/<column>" (1-based)
45	    pub const ROWSTATUS: i32 = 6; // SNMP RowStatus life-cycle (ADR-0001); not a config leaf
46	}
47	
48	/// Owned Rust view of a mapping row.
49	#[derive(Debug, Clone)]
50	pub struct MapEntry {
51	    pub uri: String,
52	    pub uri_index: String,
53	    pub val_type: i32,
54	    pub mode: i32,
55	    /// One of `col::*` — how the handler resolves this OID's value.
56	    pub table_col: i32,
57	    /// true = read from the status layer (URI had a "stat/" prefix), not config.
58	    pub is_status: bool,
59	}
60	
61	/// Exact-match lookup by OID (no instance). `None` if not found.
62	pub fn lookup_by_oid(oid: &[Oid]) -> Option<MapEntry> {
63	    let p = unsafe { ies_map_lookup_by_oid(oid.as_ptr(), oid.len()) };
64	    if p.is_null() {
65	        return None;
66	    }
67	    // Safety: `p` points to a 'static const table entry; the string fields are
68	    // NUL-terminated C strings living for the program's lifetime.
69	    let e = unsafe { &*p };
70	    Some(MapEntry {
71	        uri: c_str_to_string(e.uri),
72	        uri_index: c_str_to_string(e.uri_index),
73	        val_type: e.val_type as i32,
74	        mode: e.mode as i32,
75	        table_col: e.table_col as i32,
76	        is_status: e.is_status != 0,
77	    })
78	}
79	
80	/// Every mapped OID, in table order (so the subagent can register them all).
81	pub fn all_oids() -> Vec<Vec<Oid>> {
82	    let n = unsafe { ies_map_count() };
83	    let mut out = Vec::with_capacity(n);
84	    for i in 0..n {
85	        let p = unsafe { ies_map_entry_at(i) };
86	        if p.is_null() {
87	            continue;
88	        }
89	        let e = unsafe { &*p };
90	        // Safety: `oid` points to a 'static const subid array of length `oid_len`.
91	        let oid = unsafe { std::slice::from_raw_parts(e.oid, e.oid_len) }.to_vec();
92	        out.push(oid);
93	    }
94	    out
95	}
96	
97	/// Write `value` to the config path `config_uri` via the framework's REST
98	/// endpoint (loopback), byte-identical to the dlmod's SET. Returns 0 on success.
99	pub fn config_set(config_uri: &str, value: &str) -> i32 {
100	    let (u, v) = match (CString::new(config_uri), CString::new(value)) {
101	        (Ok(u), Ok(v)) => (u, v),
102	        _ => return -1, // interior NUL
103	    };
104	    unsafe { ies_config_set(u.as_ptr(), v.as_ptr()) }
105	}
106	
107	/// Write an INTEGER `value` to the config path `config_uri` via the framework's
108	/// REST endpoint (loopback). Returns 0 on success.
109	pub fn config_set_int(config_uri: &str, value: i64) -> i32 {
110	    let u = match CString::new(config_uri) {
111	        Ok(u) => u,
112	        Err(_) => return -1,
113	    };
114	    unsafe { ies_config_set_int(u.as_ptr(), value as std::os::raw::c_long) }
115	}
116	
117	/// Write a JSON BOOLEAN to `config_uri` via the framework's REST endpoint.
118	/// For config fields stored as booleans but exposed as SNMP INTEGER TruthValues.
119	pub fn config_set_bool(config_uri: &str, value: bool) -> i32 {
120	    let u = match CString::new(config_uri) {
121	        Ok(u) => u,
122	        Err(_) => return -1,
123	    };
124	    unsafe { ies_config_set_bool(u.as_ptr(), i32::from(value)) }
125	}
126	
127	/// PATCH a raw JSON value (`json_text`, e.g. a boolean array "[true,false,…]")
128	/// to `config_uri`. Used by the portsPbmp SET (whole-array read-modify-write).
129	pub fn config_set_json(config_uri: &str, json_text: &str) -> i32 {
130	    let (u, j) = match (CString::new(config_uri), CString::new(json_text)) {
131	        (Ok(u), Ok(j)) => (u, j),
132	        _ => return -1, // interior NUL
133	    };
134	    unsafe { ies_config_set_json(u.as_ptr(), j.as_ptr()) }
135	}
136	
137	fn c_str_to_string(p: *const c_char) -> String {
138	    if p.is_null() {
139	        String::new()
140	    } else {
141	        unsafe { CStr::from_ptr(p) }.to_string_lossy().into_owned()
142	    }
143	}

