is_index_table(const struct ies_auto_mibs_entry *e)
{
    /* turboring ring is a NAMED-KEY group ({ring1,ring2}), not an array
     * index-table — see is_turboring_ring(). Excluding it here keeps its
     * UNSUPPORTED columns (e.g. "interface", the deferred REDUNDANT_PORT) out of
     * the table entirely. Otherwise they fall through to the index-table branch
     * and emit REUSE_MAX_TABLE_ROWS rows whose path is built as
     * "<uri><row-1>/<col>" -> "turboringv20/interface", which can never resolve:
     * 16 permanently valueless OIDs that a GETNEXT has to step over one by one. */
    if (strcmp(e->uri, "config/turboringv2/ring/") == 0 ||
        strcmp(e->uri, "stat/turboringv2/ring/") == 0)
