/// GETNEXT within the mxTurboRingV2 subtree: find the next mapped OID after the
/// requested one, rewrite the varbind to it, then fill the value exactly as GET
/// does. Returning without setting a value leaves the varbind untouched, so
/// net-snmp moves on past this subtree (end of our range).
fn handle_getnext(requests: *mut c_void) -> c_int {
    let oid = match agentx::get_request_oid(requests) {
        Some(o) => o,
        None => return agentx::SNMP_ERR_NOERROR,
    };
    let oids = tr2_oids();
    // First mapped OID strictly greater than the requested one (OIDs compare
    // lexicographically, which is exactly SNMP OID ordering).
    let idx = oids.partition_point(|o| o.as_slice() <= oid.as_slice());
    match oids.get(idx) {
        Some(next) => {
            agentx::set_request_oid(requests, next);
            handle_get(requests)
        }
        None => agentx::SNMP_ERR_NOERROR,
    }
}

