cd /home/moxa/mds4xgl3/tools
timeout 120 python3 - <<'PY'
import re,glob,os
D="/home/moxa/sdc1/home/moxa/mds4xgl3/buildroot/dl/3rdparty_net_snmp/ies-auto-mibs"
def parse(p):
    out=[];cur={}
    for line in open(p,errors="replace"):
        m=re.search(r"\.(\w+)\s*=\s*(.+?),?\s*$",line)
        if m: cur[m.group(1)]=m.group(2).strip().rstrip(",").strip()
        if re.match(r"\s*\},\s*$",line) and "oid_list" in cur:
            o=tuple(int(x) for x in re.findall(r"\d+",cur["oid_list"]))
            if o: out.append((o,cur.get("iss_build","0"),os.path.basename(p),cur.get("name","?").strip('"')))
            cur={}
    return out
allx=[]
for p in glob.glob(D+"/net_*.h"): allx+=parse(p)
groups={"mx_event_port":"net_mx_event_port.h","mx_event_general":"net_mx_event_general.h",
 "mx_event_switching":"net_mx_event_switching.h","mx_event_poe":"net_mx_event_poe.h",
 "mx_email":"net_mx_email.h","mx_LoginPolicy":"net_mxLoginPolicy.h",
 "mx_PasswordPolicy":"net_mxPasswordPolicy.h","mx_RMON":"net_mx_RMON.h",
 "mx_syslogServer":"net_mx_syslogServer.h","mx_deviceIO":"net_mx_device_io.h",
 "mxTurboRingV2":"net_mx_turboring_v2.h"}
print("%-20s %-34s %s"%("group","derived subtree root","foreign OIDs under it (iss_build!=0 → UNSAFE)"))
for g,f in groups.items():
    oids=[o for o,i,fn,n in allx if fn==f]
    if not oids: print("%-20s (no entries)"%g); continue
    root=[]
    for i in range(min(len(o) for o in oids)):
        s={o[i] for o in oids}
        if len(s)==1: root.append(oids[0][i])
        else: break
    root=tuple(root)
    foreign=[(fn,n,i) for o,i,fn,n in allx if fn!=f and o[:len(root)]==root]
    bad=[x for x in foreign if x[2]!="0"]
    tag="UNSAFE" if bad else ("%d foreign(iss0)"%len(foreign) if foreign else "clean")
    print("%-20s %-34s %s"%(g,".".join(map(str,root)),tag))
PY

